import 'package:flutter/material.dart';
import '../../l10n/app_strings.dart';
import '../../services/auth_service.dart';
class RegisterScreen extends StatefulWidget { const RegisterScreen({super.key}); @override State<RegisterScreen> createState()=>_RegisterScreenState(); }
class _RegisterScreenState extends State<RegisterScreen>{ final name=TextEditingController(),email=TextEditingController(),password=TextEditingController(); String role='customer'; bool loading=false;
Future<void> submit() async { final s=LanguageScope.of(context); if(name.text.trim().isEmpty||email.text.trim().isEmpty||password.text.isEmpty){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.tr('fillRequired'))));return;} setState(()=>loading=true); try { await AuthService.instance.register(name:name.text,email:email.text,password:password.text,role:role); if(mounted)Navigator.pop(context); } catch(e){ if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('${s.tr('registerFailed')}: ${e.toString()}')));} finally{if(mounted)setState(()=>loading=false);} }
@override Widget build(BuildContext c){final s=LanguageScope.of(c);return Scaffold(appBar:AppBar(title:Text(s.tr('register'))),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:name,decoration:InputDecoration(labelText:s.tr('name'))),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:InputDecoration(labelText:s.tr('email'))),TextField(controller:password,obscureText:true,decoration:InputDecoration(labelText:s.tr('password'))),DropdownButtonFormField<String>(value:role,items:[DropdownMenuItem(value:'customer',child:Text(s.tr('customer'))),DropdownMenuItem(value:'seller',child:Text(s.tr('seller')))],onChanged:(v)=>setState(()=>role=v!),decoration:InputDecoration(labelText:s.tr('accountType'))),const SizedBox(height:20),FilledButton(onPressed:loading?null:submit,child:Text(loading?s.tr('pleaseWait'):s.tr('register')))])); }
}
